weekly_notification_summary = Ewallet.CALCULATE(
    start_date_limit=DATETIME('now', 'start of week', '-3 weeks'),
    end_date_limit=DATETIME('now', 'start of week')
).Users.WHERE(
    ISIN(country, ('US', 'Canada'))
).notifications.WHERE(
    (created_at >= start_date_limit) & (created_at < end_date_limit)
).CALCULATE(
    notification_week=DATETIME(created_at, 'start of week'),
    is_weekend=ISIN(DAYNAME(created_at), ('Saturday', 'Sunday'))
).PARTITION(
    name='weekly_notifications', by=(notification_week)
).CALCULATE(
    week=notification_week,
    total_notifications=COUNT(Notifications),
    weekend_notifications=SUM(Notifications.is_weekend)
).ORDER_BY(week.ASC())

result = Users.CALCULATE(
    user_id=uid,
    total_duration=SUM(
        sessions.WHERE(
            (session_start_ts >= "2023-06-01") & 
            (session_start_ts < "2023-06-08")
        ).CALCULATE(
            duration_seconds=DATEDIFF("seconds", session_start_ts, session_end_ts)
        ).duration_seconds
    )
).WHERE(
    HAS(sessions.WHERE(
        (session_start_ts >= "2023-06-01") & 
        (session_start_ts < "2023-06-08")
    )) == 1
).ORDER_BY(total_duration.DESC())

user_session_duration = Users.CALCULATE(
    user_id=uid,
    total_duration=ROUND(
        SUM(
            sessions.WHERE(
                (session_start_ts >= "2023-06-01") & (session_start_ts < "2023-06-08")
            ).CALCULATE(
                duration_secs=DATEDIFF("seconds", session_start_ts, session_end_ts)
            ).duration_secs
        ), 0
    )
).WHERE(
    total_duration > 0
).ORDER_BY(
    total_duration.DESC()
)

