earliest_snapshots_in_2023 = Ewallet.UserSettingSnapshots.WHERE(YEAR(snapshot_date) == 2023)
earliest_date_in_2023 = Ewallet.CALCULATE(
    min_date=MIN(earliest_snapshots_in_2023.snapshot_date)
)
result = earliest_date_in_2023.CALCULATE(
    avg_tx_limit_daily=AVG(
        earliest_snapshots_in_2023.WHERE(snapshot_date == min_date).tx_limit_daily
    ),
    avg_tx_limit_monthly=AVG(
        earliest_snapshots_in_2023.WHERE(snapshot_date == min_date).tx_limit_monthly
    ),
)

